async function loadHeight(){let b=Uint8Array.from(atob(''),c=>c.charCodeAt(0)),raw=await new Response(new Blob([b]).stream().pipeThrough(new DecompressionStream('gzip'))).arrayBuffer();placementHeight=new Uint16Array(raw)}loadHeight().catch(e=>info('بارگذاری ارتفاع ناموفق: '+e.message,true));
function info(s,warning=false){el('placeInfo').textContent=s;el('placeInfo').className=warning?'warning':''}
function fillModels(){let type=el('placeType').value;el('castleModel').replaceChildren();for(let c of castleCatalog.filter(c=>c.group===type)){let o=new Option(c.name,c.id);el('castleModel').add(o)}}fillModels();el('placeType').onchange=()=>{fillModels();updateDraft()};
function heightAt(x,z){let u=(x+1)/2*1023,v=(z+2.132)/4.264*1023;if(u<0||u>1023||v<0||v>1023)return null;let ix=Math.floor(u),iz=Math.floor(v),jx=Math.min(1023,ix+1),jz=Math.min(1023,iz+1),a=u-ix,b=v-iz;const h=(i,j)=>placementHeight[j*1024+i]/100000-.15;let original=h(ix,iz)*(1-a)*(1-b)+h(jx,iz)*a*(1-b)+h(ix,jz)*(1-a)*b+h(jx,jz)*a*b;let water=original<.015;return {height:water?.031:.025+(original-.025)*.45,water}}
function pickPoint(clientX,clientY){if(!placementHeight||!center)return null;let r=canvas.getBoundingClientRect(),nx=(clientX-r.left)/r.width*2-1,ny=1-(clientY-r.top)/r.height*2,rx=(nx-pan[0])*(r.width/r.height)/zoom,ay=(ny+.10-pan[1])/zoom;let prev=null;
 for(let depth=6;depth>=-6;depth-=.003){let yy=ay*Math.cos(pitch)+depth*Math.sin(pitch),rz=-ay*Math.sin(pitch)+depth*Math.cos(pitch),x=rx*Math.cos(yaw)+rz*Math.sin(yaw)+center[0],z=-rx*Math.sin(yaw)+rz*Math.cos(yaw)+center[2],hit=heightAt(x,z);if(!hit){prev=null;continue}let y=yy+center[1],difference=y-hit.height;if(prev&&prev.diff>0&&difference<=0){let t=prev.diff/(prev.diff-difference),px=prev.x+(x-prev.x)*t,pz=prev.z+(z-prev.z)*t,h=heightAt(px,pz);return {x:px,z:pz,y:h.height,onWater:h.water}}prev={x,z,diff:difference}}
 return null}
function listSaved(){el('savedList').replaceChildren();for(let p of saved)el('savedList').add(new Option(p.name+(p.house?' — '+p.house:''),p.id));if(selectedId)el('savedList').value=selectedId}listSaved();
function readFields(){return {name:el('castleName').value.trim(),house:el('houseName').value.trim(),type:el('placeType').value,model:el('castleModel').value,size:Number(el('castleSize').value),rotation:Number(el('castleAngle').value),lift:Number(el('castleLift').value)}}
function updateDraft(){if(!draft)return;Object.assign(draft,readFields());renderPlacements().catch(e=>info(e.message,true))}
for(let id of ['castleModel','castleSize','castleAngle','castleLift'])el(id).onchange=updateDraft;
el('startPlace').onclick=()=>{placing=true;canvas.style.cursor='crosshair';info('روی محل بنا کلیک کن. برای جابه‌جایی دوباره کلیک کن؛ دکمهٔ وسط موس یا کلیدهای جهت، نقشه را حرکت می‌دهند.')};
let pointerStart;canvas.addEventListener('pointerdown',e=>pointerStart=[e.clientX,e.clientY]);canvas.addEventListener('pointerup',e=>{if(!placing||!pointerStart||Math.hypot(e.clientX-pointerStart[0],e.clientY-pointerStart[1])>5)return;let p=pickPoint(e.clientX,e.clientY);if(!p){info('روی سطح نقشه کلیک کن؛ اگر نما افقی است از نمای بالا استفاده کن.',true);return}draft={id:selectedId||crypto.randomUUID(),...readFields(),position:p};info((p.onWater?'زیر این بنا خشکی ساخته می‌شود.':'نقطه روی خشکی قرار گرفت.')+' برای ذخیره نام را وارد کن.',p.onWater);renderPlacements().catch(e=>info(e.message,true))});
