el('savedList').onchange=()=>{selectedId=el('savedList').value;draft=JSON.parse(JSON.stringify(saved.find(p=>p.id===selectedId)));if(!draft)return;el('castleName').value=draft.name;el('houseName').value=draft.house;el('placeType').value=draft.type;fillModels();el('castleModel').value=draft.model;el('castleSize').value=draft.size;el('castleAngle').value=Math.round(draft.rotation*10)/10;el('castleLift').value=draft.lift;el('allowWater').checked=draft.position.onWater;info('انتخاب شد؛ تنظیم کن یا برای تغییر مکان، جانمایی را بزن.');renderPlacements()};
el('deletePlace').onclick=()=>{if(!selectedId)return; try{let d=JSON.parse(localStorage.getItem('valyria-deleted-seeds')||'[]');d.push(selectedId);localStorage.setItem('valyria-deleted-seeds',JSON.stringify(d))}catch{}saved=saved.filter(p=>p.id!==selectedId);draft=null;selectedId=null;try{localStorage.setItem(storageKey,JSON.stringify(saved))}catch{}try{let deleted=JSON.parse(localStorage.getItem('valyria-deleted-seeds')||'[]');for(let p of importedSeeds)if(!saved.some(q=>q.id===p.id||q.name===p.name)&&!deleted.includes(p.id))saved.push(p)}catch{}listSaved();renderPlacements();info('حذف شد.')};
el('exportPlaces').onclick=()=>{let data={schemaVersion:1,map:'westeros-seasons-original-topology',coordinateSystem:'world XYZ, Y up',placements:saved};let a=document.createElement('a');a.href=URL.createObjectURL(new Blob([JSON.stringify(data,null,2)],{type:'application/json'}));a.download='valyria-castle-placements.json';a.click();setTimeout(()=>URL.revokeObjectURL(a.href),5000)};
