window.castleAssetLoaded=(id,data)=>{assetCache.set(id,data);assetPending.get(id)?.resolve(data);assetPending.delete(id)};
async function loadAsset(id){if(assetCache.has(id))return assetCache.get(id);if(assetPending.has(id))return assetPending.get(id);let promise=mapAsset(id+'.glb').then(bytes=>{assetCache.set(id,bytes);assetPending.delete(id);return bytes}).catch(e=>{assetPending.delete(id);throw e});assetPending.set(id,promise);return promise}
