for(const mesh of meshes){const vao=gl.createVertexArray();gl.bindVertexArray(vao);buffers.push({vao});let vb=gl.createBuffer();buffers.push({buffer:vb});gl.bindBuffer(gl.ARRAY_BUFFER,vb);gl.bufferData(gl.ARRAY_BUFFER,mesh.packed,gl.STATIC_DRAW);for(const [loc,size,off] of [[0,3,0],[1,3,12],[2,4,24]]){gl.enableVertexAttribArray(loc);gl.vertexAttribPointer(loc,size,gl.FLOAT,false,40,off)}for(const loc of [3,4,5,6])gl.disableVertexAttribArray(loc);let ib=gl.createBuffer();buffers.push({buffer:ib});gl.bindBuffer(gl.ELEMENT_ARRAY_BUFFER,ib);gl.bufferData(gl.ELEMENT_ARRAY_BUFFER,mesh.indices,gl.STATIC_DRAW);groupsForCastle.push({isCastle:true,vao,count:mesh.indices.length,type:gl.UNSIGNED_INT,base:mesh.base,emission:mesh.emission,texture:null,opacity:p.ownershipStatus==='vacant'?.5:1})}
