let natureTimer=setInterval(()=>{if(main&&center){clearInterval(natureTimer);installNature()}},350);
const compass=document.createElement('canvas');compass.width=180;compass.height=180;compass.style.cssText='position:fixed;bottom:12px;left:12px;width:90px;height:90px;z-index:6;pointer-events:none';document.body.appendChild(compass);
function compassFrame(){requestAnimationFrame(compassFrame);if(document.hidden)return;let c=compass.getContext('2d');c.clearRect(0,0,180,180);c.fillStyle='rgba(242,234,211,.90)';c.strokeStyle='#9b8759';c.lineWidth=2;c.beginPath();c.arc(90,90,76,0,Math.PI*2);c.fill();c.stroke();c.save();c.translate(90,90);c.rotate(-yaw);for(let i=0;i<4;i++){c.save();c.rotate(i*Math.PI/2);c.fillStyle=i===0?'#a73531':'#5b6460';c.beginPath();c.moveTo(0,-54);c.lineTo(9,0);c.lineTo(0,12);c.lineTo(-9,0);c.closePath();c.fill();c.restore()}c.font='18px Georgia';c.textAlign='center';c.fillStyle='#343c35';c.fillText('N',0,-59);c.fillText('S',0,70);c.fillText('W',-64,6);c.fillText('E',64,6);c.restore();c.fillStyle='#bfaa75';c.beginPath();c.arc(90,90,5,0,Math.PI*2);c.fill()}requestAnimationFrame(compassFrame);
let ownershipLabel=document.createElement('label');ownershipLabel.innerHTML='وضعیت مالکیت<select id="ownershipStatus"><option value="unknown">مالکیت نامشخص</option><option value="owned">دارای مالک</option><option value="vacant">بدون مالک</option></select>';el('placeType').parentElement.before(ownershipLabel);
let selectBeforeOwnership=el('savedList').onchange;el('savedList').onchange=()=>{selectBeforeOwnership();el('ownershipStatus').value=draft?.ownershipStatus||'unknown'};el('ownershipStatus').onchange=()=>{if(draft){draft.ownershipStatus=el('ownershipStatus').value;renderPlacements()}};

let gameState={castles:[],campaigns:[],effects:[],filters:{}};
const basePlacements=structuredClone(importedSeeds);saved=[];draft=null;
const normalizeName=v=>String(v||'').normalize('NFKC').replace(/[ي]/g,'ی').replace(/[ك]/g,'ک').replace(/[\s\u200cـ]/g,'').toLowerCase();
const byGameName=new Map();for(const p of basePlacements){for(const name of [p.name,p.sourceMap?.name])if(name)byGameName.set(normalizeName(name),p)}
function findPlacement(name){const aliases={'این آف د نیلینگ من':'این آو د نیلینگ من'};return byGameName.get(normalizeName(aliases[name]||name))}
let geometryStateKey="";
function syncGameState(state){gameState=state;const key=JSON.stringify([state.castles,state.filters,state.colorMode]);if(key===geometryStateKey)return;geometryStateKey=key;Object.assign(gameRegionColors,state.colorMode==='pact'?state.pactColors||{}:state.regionColors||{});let next=[];for(const c of state.castles||[]){const original=findPlacement(c.name);if(!original)continue;let p=structuredClone(original);p.gameName=c.name;p.ownershipStatus=c.owner?'owned':'vacant';p.region=state.colorMode==='pact'?(c.owner?.pact||'none'):(c.owner?.region||c.region||p.region);p.mine=c.mine;if(state.filters?.region&&c.region!==state.filters.region)continue;let f=state.filters?.pins;if(f==='mine'&&!c.mine||f==='owned'&&!c.owner||f==='empty'&&c.owner||f==='port'&&!c.port)continue;next.push(p)}saved=next;draft=null;selectedId=null;listSaved();queueCastleRender();draw(0)}
window.addEventListener('message',event=>{if(event.origin!==location.origin||event.source!==parent)return;const msg=event.data;if(msg?.type==='valyria-map-state')syncGameState(msg.state);if(msg?.type==='valyria-map-focus'){const p=findPlacement(msg.name);if(p)focusCastle(p)}if(msg?.type==='valyria-map-fit'){fit();draw(0);queueCastleRender()}});
const previousSelect=el('savedList').onchange;el('savedList').onchange=()=>{previousSelect();if(draft)parent.postMessage({type:'valyria-map-castle',name:draft.gameName||draft.name},location.origin)};
function battleWorlds(){return (gameState.effects||[]).flatMap(e=>{let p=findPlacement(e.castle);if(p)return [[p.position.x,p.position.y+p.size*.25,p.position.z]];const a=findPlacement(e.a),b=findPlacement(e.b);if(!a||!b)return [];const t=e.position??.5;return [[a.position.x+(b.position.x-a.position.x)*t,a.position.y+(b.position.y-a.position.y)*t,a.position.z+(b.position.z-a.position.z)*t]]})}
let armyHits=[];
function paintGameArmies(ctx){armyHits=[];if(gameState.showArmies===false||!center)return;const tick=gameState.now||Date.now();for(const c of gameState.campaigns||[]){const names=c.route_path?.length>1?c.route_path:[c.from,c.to],points=names.map(findPlacement).filter(Boolean).map(p=>[p.position.x,p.position.y+p.size*.15,p.position.z]);if(points.length<2||c.arrived)continue;const utc=v=>Date.parse(/[zZ]$|[+-]\d\d:\d\d$/.test(v)?v:v+'Z');const start=utc(c.departed_at),end=utc(c.arrival_at);let progress=Math.max(0,Math.min(1,(tick-start)/Math.max(1,end-start)));if(!Number.isFinite(progress)||progress>=1)continue;const lengths=points.slice(1).map((q,i)=>Math.hypot(q[0]-points[i][0],q[2]-points[i][2])),total=lengths.reduce((a,b)=>a+b,0);let remain=progress*total,world=points.at(-1);for(let i=0;i<lengths.length;i++){if(remain<=lengths[i]||i===lengths.length-1){let t=remain/Math.max(.00001,lengths[i]);world=points[i].map((v,j)=>v+(points[i+1][j]-v)*t);break}remain-=lengths[i]}let [x,y]=projectEffect(world);if(x<0||y<0||x>canvas.clientWidth||y>canvas.clientHeight)continue;ctx.fillStyle=c.mine?'#e4b94c':'#e9e8df';ctx.strokeStyle='#17232b';ctx.lineWidth=2;ctx.beginPath();ctx.arc(x,y,8,0,Math.PI*2);ctx.fill();ctx.stroke();ctx.fillStyle='#17232b';ctx.font='12px sans-serif';ctx.fillText('⚔',x,y+4);armyHits.push({x,y,id:c.id})}}
canvas.addEventListener('pointerup',e=>{if(!markerDown||Math.hypot(e.clientX-markerDown[0],e.clientY-markerDown[1])>5)return;const rect=canvas.getBoundingClientRect(),hit=armyHits.find(a=>Math.hypot(a.x-e.clientX+rect.left,a.y-e.clientY+rect.top)<12);if(hit)parent.postMessage({type:'valyria-map-army',id:hit.id},location.origin)});
canvas.addEventListener('webglcontextlost',event=>{event.preventDefault();parent.postMessage({type:'valyria-map-error'},location.origin)});
parent.postMessage({type:'valyria-map-ready'},location.origin);

function paintRegionAreas(ctx){if(!gameState.showBorders||!center)return;const regions=new Map();for(const p of basePlacements){let a=regions.get(p.region)||[];a.push(p);regions.set(p.region,a)}ctx.save();for(const [rid,rows]of regions){if(rows.length<3)continue;let points=rows.map(p=>projectEffect([p.position.x,p.position.y,p.position.z])).sort((a,b)=>a[0]-b[0]||a[1]-b[1]);const cross=(a,b,c)=>(b[0]-a[0])*(c[1]-a[1])-(b[1]-a[1])*(c[0]-a[0]);let lower=[],upper=[];for(const p of points){while(lower.length>1&&cross(lower.at(-2),lower.at(-1),p)<=0)lower.pop();lower.push(p)}for(const p of [...points].reverse()){while(upper.length>1&&cross(upper.at(-2),upper.at(-1),p)<=0)upper.pop();upper.push(p)}let hull=[...lower.slice(0,-1),...upper.slice(0,-1)];ctx.strokeStyle=gameState.regionColors?.[rid]||'#c8b377';ctx.lineWidth=1.5;ctx.setLineDash([6,4]);ctx.beginPath();hull.forEach((p,i)=>i?ctx.lineTo(...p):ctx.moveTo(...p));ctx.closePath();ctx.stroke()}ctx.restore()}

let initialFocusDone=false;const initialFocusTimer=setInterval(()=>{if(!center||!gameState.castles?.length)return;clearInterval(initialFocusTimer);const mine=gameState.castles.find(c=>c.mine),p=mine&&findPlacement(mine.name);if(p)focusCastle(p);initialFocusDone=true},400);
